mapper.select:
SELECT * FROM pcd_space_join_request_table
WHERE space_id = #{spaceId,typeHandler=org.project.util.UUIDBinaryTypeHandler}
ORDER BY created_at DESC

SELECT * FROM pcd_space_join_request_table
WHERE space_id = #{spaceId,typeHandler=org.project.util.UUIDBinaryTypeHandler}
AND status = #{status}
ORDER BY created_at DESC

SELECT * FROM pcd_space_join_request_table
WHERE space_id = #{spaceId,typeHandler=org.project.util.UUIDBinaryTypeHandler}
AND user_id = #{userId,typeHandler=org.project.util.UUIDBinaryTypeHandler}
ORDER BY created_at DESC LIMIT 1

SELECT * FROM pcd_space_join_request_table
WHERE user_id = #{userId,typeHandler=org.project.util.UUIDBinaryTypeHandler}
ORDER BY created_at DESC

mapper.delete:
DELETE FROM pcd_space_join_request_table
WHERE request_id = #{requestId} AND user_id = #{userId,typeHandler=org.project.util.UUIDBinaryTypeHandler}
  AND status = 'pending'
